import 'package:flutter/material.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';

class BasicMapScreen extends StatefulWidget {
  const BasicMapScreen({super.key});

  @override
  State<BasicMapScreen> createState() => _BasicMapScreenState();
}

class _BasicMapScreenState extends State<BasicMapScreen> {
  GoogleMapController? _mapController;

  // 서울 시청 좌표
  static const _initialPosition = CameraPosition(
    target: LatLng(37.5666805, 126.9784147),
    zoom: 15,
  );

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Google Maps')),
      body: GoogleMap(
        initialCameraPosition: _initialPosition,
        onMapCreated: (controller) {
          _mapController = controller;
        },
        // 지도 타입: normal, satellite, terrain, hybrid
        mapType: MapType.normal,
        // 현재 위치 버튼
        myLocationButtonEnabled: true,
        // 현재 위치 표시 (권한 필요)
        myLocationEnabled: false,
        // 줌 컨트롤
        zoomControlsEnabled: true,
        // 나침반
        compassEnabled: true,
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () {
          // 초기 위치로 이동
          _mapController?.animateCamera(
            CameraUpdate.newCameraPosition(_initialPosition),
          );
        },
        child: const Icon(Icons.center_focus_strong),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';

class MarkerMapScreen extends StatefulWidget {
  const MarkerMapScreen({super.key});

  @override
  State<MarkerMapScreen> createState() => _MarkerMapScreenState();
}

class _MarkerMapScreenState extends State<MarkerMapScreen> {
  final Set<Marker> _markers = {};

  @override
  void initState() {
    super.initState();
    _addMarkers();
  }

  void _addMarkers() {
    setState(() {
      _markers.addAll([
        Marker(
          markerId: const MarkerId('seoul_city_hall'),
          position: const LatLng(37.5666805, 126.9784147),
          infoWindow: const InfoWindow(
            title: '서울시청',
            snippet: '서울특별시 중구 세종대로 110',
          ),
          icon: BitmapDescriptor.defaultMarkerWithHue(
            BitmapDescriptor.hueRed,
          ),
          onTap: () {
            debugPrint('서울시청 마커 탭됨');
          },
        ),
        Marker(
          markerId: const MarkerId('gwanghwamun'),
          position: const LatLng(37.5759, 126.9769),
          infoWindow: const InfoWindow(
            title: '광화문',
            snippet: '조선시대 경복궁의 정문',
          ),
          icon: BitmapDescriptor.defaultMarkerWithHue(
            BitmapDescriptor.hueBlue,
          ),
        ),
        Marker(
          markerId: const MarkerId('namsan_tower'),
          position: const LatLng(37.5512, 126.9882),
          infoWindow: const InfoWindow(
            title: 'N서울타워',
            snippet: '서울의 랜드마크',
          ),
          icon: BitmapDescriptor.defaultMarkerWithHue(
            BitmapDescriptor.hueGreen,
          ),
        ),
      ]);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('마커')),
      body: GoogleMap(
        initialCameraPosition: const CameraPosition(
          target: LatLng(37.5666805, 126.9784147),
          zoom: 13,
        ),
        markers: _markers,
        onTap: (position) {
          // 지도 탭 시 새 마커 추가
          final markerId = MarkerId('marker_${_markers.length}');
          setState(() {
            _markers.add(
              Marker(
                markerId: markerId,
                position: position,
                infoWindow: InfoWindow(
                  title: '새 마커',
                  snippet: '${position.latitude.toStringAsFixed(4)}, ${position.longitude.toStringAsFixed(4)}',
                ),
              ),
            );
          });
        },
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';

class ShapesMapScreen extends StatefulWidget {
  const ShapesMapScreen({super.key});

  @override
  State<ShapesMapScreen> createState() => _ShapesMapScreenState();
}

class _ShapesMapScreenState extends State<ShapesMapScreen> {
  final Set<Polyline> _polylines = {};
  final Set<Polygon> _polygons = {};
  final Set<Circle> _circles = {};

  @override
  void initState() {
    super.initState();
    _addShapes();
  }

  void _addShapes() {
    // 폴리라인 (경로)
    _polylines.add(
      Polyline(
        polylineId: const PolylineId('route_1'),
        color: Colors.blue,
        width: 5,
        points: const [
          LatLng(37.5666805, 126.9784147), // 서울시청
          LatLng(37.5759, 126.9769),       // 광화문
          LatLng(37.5796, 126.9770),       // 경복궁
        ],
        patterns: [
          PatternItem.dash(20),
          PatternItem.gap(10),
        ],
      ),
    );

    // 폴리곤 (영역)
    _polygons.add(
      Polygon(
        polygonId: const PolygonId('area_1'),
        fillColor: Colors.green.withOpacity(0.3),
        strokeColor: Colors.green,
        strokeWidth: 2,
        points: const [
          LatLng(37.56, 126.97),
          LatLng(37.56, 126.99),
          LatLng(37.58, 126.99),
          LatLng(37.58, 126.97),
        ],
      ),
    );

    // 원
    _circles.add(
      Circle(
        circleId: const CircleId('circle_1'),
        center: const LatLng(37.5512, 126.9882), // 남산타워
        radius: 500, // 미터 단위
        fillColor: Colors.red.withOpacity(0.2),
        strokeColor: Colors.red,
        strokeWidth: 2,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('도형 그리기')),
      body: GoogleMap(
        initialCameraPosition: const CameraPosition(
          target: LatLng(37.5666805, 126.9784147),
          zoom: 13,
        ),
        polylines: _polylines,
        polygons: _polygons,
        circles: _circles,
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';

class CameraControlScreen extends StatefulWidget {
  const CameraControlScreen({super.key});

  @override
  State<CameraControlScreen> createState() => _CameraControlScreenState();
}

class _CameraControlScreenState extends State<CameraControlScreen> {
  GoogleMapController? _mapController;
  String _currentPosition = '';
  double _currentZoom = 15;

  final List<Map<String, dynamic>> _locations = [
    {'name': '서울', 'lat': 37.5666805, 'lng': 126.9784147},
    {'name': '부산', 'lat': 35.1796, 'lng': 129.0756},
    {'name': '제주', 'lat': 33.4996, 'lng': 126.5312},
    {'name': '경주', 'lat': 35.8562, 'lng': 129.2250},
  ];

  void _moveToLocation(double lat, double lng, {double zoom = 15}) {
    _mapController?.animateCamera(
      CameraUpdate.newCameraPosition(
        CameraPosition(
          target: LatLng(lat, lng),
          zoom: zoom,
          tilt: 45, // 기울기
          bearing: 30, // 방향
        ),
      ),
    );
  }

  void _zoomIn() {
    _mapController?.animateCamera(CameraUpdate.zoomIn());
  }

  void _zoomOut() {
    _mapController?.animateCamera(CameraUpdate.zoomOut());
  }

  void _fitBounds() {
    // 모든 위치가 보이도록 줌 조절
    final bounds = LatLngBounds(
      southwest: const LatLng(33.0, 125.0),
      northeast: const LatLng(38.0, 130.0),
    );
    _mapController?.animateCamera(
      CameraUpdate.newLatLngBounds(bounds, 50),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('카메라 제어')),
      body: Column(
        children: [
          // 위치 선택 버튼
          SizedBox(
            height: 50,
            child: ListView.builder(
              scrollDirection: Axis.horizontal,
              itemCount: _locations.length,
              itemBuilder: (context, index) {
                final loc = _locations[index];
                return Padding(
                  padding: const EdgeInsets.all(8),
                  child: ElevatedButton(
                    onPressed: () => _moveToLocation(loc['lat'], loc['lng']),
                    child: Text(loc['name']),
                  ),
                );
              },
            ),
          ),
          // 지도
          Expanded(
            child: Stack(
              children: [
                GoogleMap(
                  initialCameraPosition: const CameraPosition(
                    target: LatLng(37.5666805, 126.9784147),
                    zoom: 15,
                  ),
                  onMapCreated: (controller) {
                    _mapController = controller;
                  },
                  onCameraMove: (position) {
                    setState(() {
                      _currentPosition =
                          '${position.target.latitude.toStringAsFixed(4)}, '
                          '${position.target.longitude.toStringAsFixed(4)}';
                      _currentZoom = position.zoom;
                    });
                  },
                  onCameraIdle: () {
                    debugPrint('카메라 이동 완료');
                  },
                ),
                // 현재 위치 정보 표시
                Positioned(
                  top: 10,
                  left: 10,
                  child: Container(
                    padding: const EdgeInsets.all(8),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(8),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withOpacity(0.2),
                          blurRadius: 4,
                        ),
                      ],
                    ),
                    child: Text(
                      '위치: $_currentPosition\n줌: ${_currentZoom.toStringAsFixed(1)}',
                      style: const TextStyle(fontSize: 12),
                    ),
                  ),
                ),
                // 줌 버튼
                Positioned(
                  right: 10,
                  bottom: 100,
                  child: Column(
                    children: [
                      FloatingActionButton.small(
                        heroTag: 'zoom_in',
                        onPressed: _zoomIn,
                        child: const Icon(Icons.add),
                      ),
                      const SizedBox(height: 8),
                      FloatingActionButton.small(
                        heroTag: 'zoom_out',
                        onPressed: _zoomOut,
                        child: const Icon(Icons.remove),
                      ),
                      const SizedBox(height: 8),
                      FloatingActionButton.small(
                        heroTag: 'fit',
                        onPressed: _fitBounds,
                        child: const Icon(Icons.zoom_out_map),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
